export const defaultGreeting = 'hi';

export function greet(name?: string): string {
  const trimmed = name?.trim();
  if (!trimmed) {
    return defaultGreeting;
  }
  return `${defaultGreeting}, ${trimmed}`;
}

import assert from 'node:assert/strict';
import test from 'node:test';

import { defaultGreeting, greet } from './index.ts';

test('defaultGreeting is exported', () => {
  assert.equal(defaultGreeting, 'hi');
});

test('greet returns the greeting alone when name is missing', () => {
  assert.equal(greet(), defaultGreeting);
  assert.equal(greet(undefined), defaultGreeting);
});

test('greet returns the greeting alone when name is blank', () => {
  assert.equal(greet(''), defaultGreeting);
  assert.equal(greet('   '), defaultGreeting);
  assert.equal(greet('\t\n'), defaultGreeting);
});

test('greet includes the name when provided', () => {
  assert.equal(greet('Ada'), `${defaultGreeting}, Ada`);
  assert.equal(greet('  Ada  '), `${defaultGreeting}, Ada`);
});

